create table if not exists public.partner_commission_slabs(id uuid primary key default gen_random_uuid(),name text not null,business_type text not null check(business_type in('fresh','port')),category_id uuid not null references public.categories(id) on delete restrict,slab_ranges jsonb not null default'[]'::jsonb,high_categories integer not null default 0 check(high_categories>=0),average_categories integer not null default 0 check(average_categories>=0),low_categories integer not null default 0 check(low_categories>=0),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(name,business_type,category_id));
create index if not exists partner_commission_slabs_lookup_idx on public.partner_commission_slabs(category_id,business_type,active);notify pgrst,'reload schema';
